// Sentinel UI — read-only monitor. Polls Sepolia (feed + vault) and Lasna
// (sentinel) and renders price, escrow, orders and recent events.
// Config comes from web/config.js (generated by scripts/deploy-all.mjs).
// If the RPCs are unreachable the page falls back to web/snapshot.json when
// present (used for the demo video stills).
(async () => {
  const $ = (id) => document.getElementById(id);
  const cfg = window.SENTINEL_CONFIG || {};
  const short = (a) => (a ? a.slice(0, 6) + "…" + a.slice(-4) : "—");
  const fmtUSD = (v) => "$" + (Number(v) / 1e8).toFixed(2);
  const fmtTok = (v) => Number(window.ethers.formatEther(v)).toFixed(2);

  const FEED_ABI = ["function getPrice() view returns (uint256)", "event PriceUpdated(uint256 price, uint256 timestamp)"];
  const TOKEN_ABI = ["function balanceOf(address) view returns (uint256)"];
  const VAULT_ABI = [
    "function nextOrderId() view returns (uint256)",
    "function getOrder(uint256) view returns (tuple(address user, uint256 amount, uint256 stopPrice, bool isTakeProfit, bool active, bool executed))",
    "event OrderCreated(uint256 indexed orderId, address indexed user, uint256 amount, uint256 stopPrice, bool isTakeProfit)",
    "event StopLossExecuted(uint256 indexed orderId, address indexed user, uint256 amount, uint256 price, uint256 timestamp)",
    "event OrderCancelled(uint256 indexed orderId, address indexed user, uint256 amount)",
  ];
  const SENTINEL_ABI = [
    "function armedOrderCount() view returns (uint256)",
    "event OrderArmed(uint256 indexed orderId, address indexed user, uint256 stopPrice, bool isTakeProfit)",
    "event OrderTriggered(uint256 indexed orderId, address indexed user, uint256 price, uint256 timestamp)",
  ];

  function renderSnapshot(s) {
    $("price").textContent = fmtUSD(s.price);
    $("priceTime").textContent = s.priceTime || "—";
    $("escrow").textContent = s.escrow;
    $("myBal").textContent = s.myBal;
    $("armed").textContent = String(s.armed);
    $("sentinelBal").textContent = s.sentinelBal;
    $("orders").innerHTML = s.orders
      .map(
        (o) =>
          `<tr><td>#${o.id}</td><td>${o.type}</td><td>${o.amount} sUSD</td><td>${o.trigger}</td>` +
          `<td><span class="pill ${o.statusClass}">${o.status}</span></td></tr>`
      )
      .join("");
    $("events").innerHTML = s.events.map((e) => `<div class="kv"><span>${e.text}</span><b>${e.when}</b></div>`).join("");
    $("status").textContent = "snapshot — " + (s.note || "");
    $("status").className = "ok";
  }

  async function renderLive() {
    const sep = new window.ethers.JsonRpcProvider(cfg.sepoliaRpc);
    const las = new window.ethers.JsonRpcProvider(cfg.lasnaRpc);
    const feed = new window.ethers.Contract(cfg.feed, FEED_ABI, sep);
    const token = new window.ethers.Contract(cfg.token, TOKEN_ABI, sep);
    const vault = new window.ethers.Contract(cfg.vault, VAULT_ABI, sep);
    const sentinel = new window.ethers.Contract(cfg.sentinel, SENTINEL_ABI, las);

    const [price, escrow, armed, sBal] = await Promise.all([
      feed.getPrice(),
      token.balanceOf(cfg.vault),
      sentinel.armedOrderCount(),
      las.getBalance(cfg.sentinel),
    ]);
    const myBal = cfg.deployer ? await token.balanceOf(cfg.deployer) : 0n;

    $("price").textContent = fmtUSD(price);
    $("escrow").textContent = fmtTok(escrow);
    $("armed").textContent = String(armed);
    $("sentinelBal").textContent = Number(window.ethers.formatEther(sBal)).toFixed(3) + " lREACT";
    $("myBal").textContent = fmtTok(myBal) + " sUSD";
    $("feedAddr").textContent = short(cfg.feed);
    $("vaultAddr").textContent = short(cfg.vault);
    $("sentinelAddr").textContent = short(cfg.sentinel);
    $("linkFeed").href = "https://sepolia.etherscan.io/address/" + cfg.feed;
    $("linkVault").href = "https://sepolia.etherscan.io/address/" + cfg.vault;
    $("linkSentinel").href = "https://lasna.reactscan.net/address/" + cfg.sentinel;

    const n = Number(await vault.nextOrderId());
    const rows = [];
    for (let i = 0; i < n; i++) {
      const o = await vault.getOrder(i);
      const status = o.executed ? ["Executed", "executed"] : o.active ? ["Armed", "armed"] : ["Cancelled", "cancelled"];
      rows.push(
        `<tr><td>#${i}</td><td>${o.isTakeProfit ? "Take-profit" : "Stop-loss"}</td>` +
          `<td>${fmtTok(o.amount)} sUSD</td><td>${fmtUSD(o.stopPrice)}</td>` +
          `<td><span class="pill ${status[1]}">${status[0]}</span></td></tr>`
      );
    }
    $("orders").innerHTML = rows.length ? rows.join("") : '<tr><td colspan="5" class="muted">no orders yet</td></tr>';

    const [created, executed, triggered] = await Promise.all([
      vault.queryFilter(vault.filters.OrderCreated, -10000),
      vault.queryFilter(vault.filters.StopLossExecuted, -10000),
      sentinel.queryFilter(sentinel.filters.OrderTriggered, -10000),
    ]);
    const evs = [
      ...created.map((e) => ({ t: `Order #${e.args.orderId} created — ${fmtTok(e.args.amount)} sUSD @ ${fmtUSD(e.args.stopPrice)}`, b: e.blockNumber })),
      ...triggered.map((e) => ({ t: `Sentinel triggered order #${e.args.orderId} at ${fmtUSD(e.args.price)}`, b: e.blockNumber })),
      ...executed.map((e) => ({ t: `Vault released ${fmtTok(e.args.amount)} sUSD for order #${e.args.orderId}`, b: e.blockNumber })),
    ]
      .sort((a, b) => b.b - a.b)
      .slice(0, 8);
    $("events").innerHTML = evs.length
      ? evs.map((e) => `<div class="kv"><span>${e.t}</span><b>block ${e.b}</b></div>`).join("")
      : '<div class="muted">no events yet</div>';

    const [feedBlock, lasBlock] = await Promise.all([sep.getBlockNumber(), las.getBlockNumber()]);
    $("priceTime").textContent = "Sepolia #" + feedBlock + " · Lasna #" + lasBlock;
    $("status").textContent = "live — Sepolia #" + feedBlock + " · Lasna #" + lasBlock;
    $("status").className = "ok";
  }

  try {
    await renderLive();
    setInterval(() => renderLive().catch(() => {}), 15000);
  } catch (e) {
    console.warn("live RPC failed, trying snapshot:", e.message);
    if (window.SENTINEL_SNAPSHOT) {
      renderSnapshot(window.SENTINEL_SNAPSHOT);
      return;
    }
    try {
      const res = await fetch("snapshot.json");
      if (!res.ok) throw new Error("no snapshot");
      renderSnapshot(await res.json());
    } catch {
      $("status").textContent = "could not reach the chains — check web/config.js";
      $("orders").innerHTML = '<tr><td colspan="5" class="muted">unreachable</td></tr>';
      $("events").textContent = "unreachable";
    }
  }
})();
